ALTER TABLE chat_promotion ADD COLUMN body TEXT NOT NULL DEFAULT '';
ALTER TABLE chat_promotion ADD COLUMN cta_text VARCHAR(80) NOT NULL DEFAULT 'Explore offerings ↗';
ALTER TABLE chat_promotion ADD COLUMN starts_at TIMESTAMPTZ;
ALTER TABLE chat_promotion ADD COLUMN ends_at TIMESTAMPTZ;
ALTER TABLE chat_promotion ADD CONSTRAINT campaign_dates CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at);
-- Replace the four generic demo nudges with one tailored campaign per category.
UPDATE chat_promotion SET active=false WHERE id IN (
 SELECT md5('apna-demo-promotion-'||c.slug||'-'||d.shop)::uuid FROM community c
 CROSS JOIN (VALUES('Neighbour Kitchen'),('Cool Sips'),('Weekend Bakehouse'),('Creative Club')) d(shop)
 WHERE c.slug IN ('tridasa','sayuk'));
