INSERT INTO chat_promotion(id,community_id,offering_id,title,body,cta_text,kind) SELECT md5('apna-demo-category-campaign-'||c.slug||'-'||'Food & Tiffin')::uuid,c.id,o.id,'Home-cooked, zero effort','Anitha’s Neighbour Kitchen has a vegetarian lunch box in the catalog. Give your kitchen a break?','Show me lunch 🍱','promoted' FROM community c JOIN LATERAL(SELECT o.id FROM offering o JOIN provider p ON p.id=o.provider_id JOIN category k ON k.id=o.category_id WHERE p.community_id=c.id AND p.shop_name LIKE '% · Demo' AND k.name='Food & Tiffin' AND o.is_available ORDER BY CASE WHEN p.shop_name IN ('Home Sparkle · Demo','Bright Home · Demo','Creative Club · Demo') THEN 0 ELSE 1 END,o.created_at,o.name LIMIT 1) o ON true WHERE c.slug IN ('tridasa','sayuk') ON CONFLICT(id) DO NOTHING;
